def retry_mechanism(retries=3, delay=10):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            logging.basicConfig(level=logging.INFO)
            last_exception = None
            for attempt in range(retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_exception = e
                    logging.info(f"Attempt {attempt + 1} failed: {e}")
                    if attempt < retries - 1:
                        time.sleep(delay)
            raise last_exception
        return wrapper
    return decorator


class Redfishcommon(object):
    def __init__(self, conn_details, token_details):
        """
        Redfish interface constructor, initializes connection info, and token info.

        :param ConnectionDetails conn_details:  calss with parameters host ip, username, password, port, redfish_version
        :param TokenDetails token_details: calss with parameters access_token, token expired timer, session id
        """
        self.conn_details = conn_details
        self.token_details = token_details

        self.systems = SystemsCommon(conn_details, self.token_details.access_token)
        self.root = RootCommon(conn_details, self.token_details.access_token)
        self.update = UpdateCommon(conn_details, self.token_details.access_token)
        self.account = AccountCommon(conn_details, self.token_details.access_token)
        self.views = ViewsCommon(conn_details, self.token_details.access_token)
        self.chassis = ChassisCommon(conn_details, self.token_details.access_token)
        self.managers = ManagersCommon(conn_details, self.token_details.access_token)
        self.task = TaskCommon(conn_details, self.token_details.access_token)

